package com.makemytrip.makemytrip.services;
import com.makemytrip.makemytrip.models.*; import com.makemytrip.makemytrip.repositories.*; import org.springframework.stereotype.Service; import org.springframework.beans.factory.annotation.Value; import org.springframework.data.mongodb.core.MongoTemplate; import org.springframework.data.mongodb.core.query.*; import java.time.*; import java.util.*;
@Service public class FeatureService {
 private final MongoTemplate mongo; private final BookingRepository bookings;
 public FeatureService(MongoTemplate mongo,BookingRepository bookings){this.mongo=mongo;this.bookings=bookings;}
 public Booking owned(String id,String user){Booking b=bookings.findById(id).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND,"Booking not found"));if(!Objects.equals(b.getUserId(),user))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"Booking belongs to another user");return b;}
 public FeatureRecord put(String kind,String parent,String owner,Map<String,Object> data){FeatureRecord f=new FeatureRecord();f.kind=kind;f.parentId=parent;f.ownerId=owner;f.data=data;return mongo.save(f);}
 public List<FeatureRecord> list(String kind,String parent){Query q=new Query(Criteria.where("kind").is(kind));if(parent!=null)q.addCriteria(Criteria.where("parentId").is(parent));return mongo.find(q,FeatureRecord.class);}
 public FeatureRecord get(String id){return mongo.findById(id,FeatureRecord.class);}
 public FeatureRecord claimSeat(String flight,String seat,String user){Query q=new Query(Criteria.where("kind").is("SEAT").and("parentId").is(flight).and("data.seatNumber").is(seat).and("data.status").is("AVAILABLE"));Update u=new Update().set("data.status","BOOKED").set("ownerId",user).set("updatedAt",Instant.now());return mongo.findAndModify(q,u,org.springframework.data.mongodb.core.FindAndModifyOptions.options().returnNew(true),FeatureRecord.class);}
 public boolean releaseSeat(String flight,String seat,String user){Query q=new Query(Criteria.where("kind").is("SEAT").and("parentId").is(flight).and("data.seatNumber").is(seat).and("data.status").is("BOOKED").and("ownerId").is(user));Update u=new Update().set("data.status","AVAILABLE").unset("ownerId").set("updatedAt",Instant.now());return mongo.updateFirst(q,u,FeatureRecord.class).getModifiedCount()==1;}
 public boolean claimRoom(String hotel,String type){Query q=new Query(Criteria.where("kind").is("ROOM").and("parentId").is(hotel).and("data.roomType").is(type).and("data.availableQuantity").gt(0));Update u=new Update().inc("data.availableQuantity",-1).set("updatedAt",Instant.now());return mongo.findAndModify(q,u,org.springframework.data.mongodb.core.FindAndModifyOptions.options().returnNew(true),FeatureRecord.class)!=null;}
 public void releaseRoom(String hotel,String type){Query q=new Query(Criteria.where("kind").is("ROOM").and("parentId").is(hotel).and("data.roomType").is(type));mongo.updateFirst(q,new Update().inc("data.availableQuantity",1).set("updatedAt",Instant.now()),FeatureRecord.class);}
 public FeatureRecord update(String id,Map<String,Object> data,String owner){FeatureRecord f=get(id);if(f==null)throw new RuntimeException("Feature record not found");if(f.ownerId!=null&&!Objects.equals(f.ownerId,owner))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN);f.data=data;f.updatedAt=Instant.now();return mongo.save(f);}
}
